SELECT COUNT(*)
FROM reservations
WHERE book_id = #{bookId}
  AND status = 'READY'
  AND hold_until > #{now}

SELECT COUNT(*)
FROM reservations
WHERE book_id = #{bookId}
  AND reader_id = #{readerId}
  AND status IN ('WAITING', 'READY')

SELECT id, book_id, reader_id, status, created_at, ready_at, hold_until
FROM reservations
WHERE book_id = #{bookId}
  AND reader_id = #{readerId}
  AND status = 'READY'
  AND hold_until > #{now}
LIMIT 1

SELECT id, book_id, reader_id, status, created_at, ready_at, hold_until
FROM reservations
WHERE book_id = #{bookId}
  AND status = 'READY'
  AND hold_until < #{now}
ORDER BY ready_at ASC

mapper.update:
UPDATE reservations
SET status = #{status},
    ready_at = #{readyAt},
    hold_until = #{holdUntil}
WHERE id = #{id}
